<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('admin');$pdo=db();
if(is_post()){verify_csrf();$id=(int)($_POST['request_id']??0);$action=$_POST['action']??'';if($action!=='close'){http_response_code(400);exit('Invalid action.');}$stmt=$pdo->prepare("UPDATE clothing_requests SET status='closed' WHERE id=? AND status='active'");$stmt->execute([$id]);if($stmt->rowCount()){log_activity($pdo,'closed a request as administrator',(int)$user['id'],'request',$id);flash('success','Request closed system-wide.');}else flash('error','Only active requests can be closed.');redirect('admin/requests.php');}
$stmt=$pdo->query("SELECT cr.*,c.organization_name,COALESCE((SELECT SUM(quantity_needed) FROM request_requirements WHERE request_id=cr.id),0) needed,COALESCE((SELECT SUM(di.quantity) FROM donation_items di JOIN donation_pledges dp ON dp.id=di.pledge_id JOIN request_requirements rr ON rr.id=di.request_requirement_id WHERE rr.request_id=cr.id AND dp.status='received'),0) received FROM clothing_requests cr JOIN charities c ON c.id=cr.charity_id ORDER BY cr.created_at DESC");$requests=$stmt->fetchAll();$pageTitle='All clothing requests';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">System-wide visibility</span><h1>All clothing requests</h1><p>Review live and historical needs from every organisation.</p></div><a class="button button-outline" href="<?=e(url('admin/dashboard.php'))?>">Admin overview</a></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Request</th><th>Charity</th><th>Need / received</th><th>Urgency</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($requests as $r):?><tr><td><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['location'])?></span></td><td><?=e($r['organization_name'])?></td><td><?=$r['needed']?> / <?=$r['received']?></td><td><span class="chip chip-sun"><?=e($r['urgency'])?></span></td><td><span class="status <?=e(status_class($r['status']))?>"><?=e($r['status'])?></span></td><td><?php if($r['status']==='active'):?><form method="post" data-loading data-confirm="Close this request? It will no longer receive pledges."><?=csrf_field()?><input type="hidden" name="request_id" value="<?=$r['id']?>"><input type="hidden" name="action" value="close"><button class="button button-danger button-small">Close</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
